import itertools, random, sys
from collections import defaultdict

def arborescences(C, root):
    others = [x for x in C if x != root]
    res = []
    for combo in itertools.product([y for y in C if y != root] * 0 or [y for y in C], repeat=0) if False else itertools.product(C, repeat=len(others)):
        ok = True
        edges = []
        for i, w in enumerate(others):
            p = combo[i]
            if p == w:
                ok = False; break
            edges.append((p, w))
        if not ok: continue
        par = {w: p for (p, w) in edges}
        good = True
        for w in others:
            seen = set(); x = w
            while x != root:
                if x in seen: good = False; break
                seen.add(x); x = par[x]
            if not good: break
        if good:
            res.append(frozenset(edges))
    return res

def directed_arcs(n, links):
    # arc key: (link_index, direction) -> (u,v) endpoints in traversal order
    arcs = []
    for li, (u, v) in enumerate(links):
        arcs.append((li, 0, u, v))
        arcs.append((li, 1, v, u))
    return arcs

def all_simple_paths(n, links, s, t, forbidden):
    # forbidden: set of vertices that cannot be internal
    adj = defaultdict(list)
    for li, (u, v) in enumerate(links):
        adj[u].append((v, li, 0))
        adj[v].append((u, li, 1))
    res = []
    def dfs(cur, visited, arcsacc):
        if cur == t:
            res.append(tuple(arcsacc)); return
        for (nxt, li, d) in adj[cur]:
            if nxt in visited: continue
            if nxt == t:
                visited.add(nxt); arcsacc.append((li,d))
                dfs(nxt, visited, arcsacc)
                arcsacc.pop(); visited.discard(nxt)
            else:
                if nxt in forbidden: continue
                visited.add(nxt); arcsacc.append((li,d))
                dfs(nxt, visited, arcsacc)
                arcsacc.pop(); visited.discard(nxt)
    dfs(s, {s}, [])
    return res

def cut_deficient(n, links, caps, parts, r):
    D = sum(r.values())
    if D == 0: return None
    best = None
    for mask in range(1, 1 << n):
        S = [v for v in range(n) if mask >> v & 1]
        sc = [v for v in parts if mask >> v & 1]
        if not sc or len(sc) == len(parts): continue
        rs = sum(r[v] for v in sc)
        capsum = 0
        for li, (u, v) in enumerate(links):
            if ((mask >> u & 1) != (mask >> v & 1)):
                capsum += caps[li]
        if capsum < rs:
            return S
    return None

def brute_feasible(n, links, caps, parts, r, node_limit=4_000_000):
    D = sum(r.values())
    if D == 0: return True, None
    # per-origin arborescence lists
    origins = [v for v in parts if r[v] > 0]
    per_origin = []
    for v in origins:
        arbs = arborescences(parts, v)
        # weight vectors summing to r[v]
        k = len(arbs)
        vecs = []
        def rec(i, rem, cur):
            if i == k-1:
                vecs.append(tuple(cur+[rem])); return
            for x in range(rem+1):
                rec(i+1, rem-x, cur+[x])
        rec(0, r[v], [])
        per_origin.append((v, arbs, vecs))
    # paths per pair
    nonparts = set(range(n)) - set(parts)
    pathmap = {}
    for u in parts:
        for w in parts:
            if u != w:
                ps = all_simple_paths(n, links, u, w, nonparts)
                if not ps: return False, ('nopath', u, w)
                pathmap[(u,w)] = ps
    arcidx = {}
    for li in range(len(links)):
        arcidx[(li,0)] = 2*li
        arcidx[(li,1)] = 2*li+1
    total = 2*len(links)
    capsvec = []
    for li in range(len(links)):
        capsvec.append(caps[li]); capsvec.append(caps[li])
    # precompute path load vectors
    ploads = {}
    for key, ps in pathmap.items():
        ploads[key] = [[arcidx[a] for a in p] for p in ps]
    # distributions per pair given amount
    def dists(k, amount):
        res = []
        def rec(i, rem, cur):
            if i == k-1:
                res.append(tuple(cur+[rem])); return
            for x in range(rem+1):
                rec(i+1, rem-x, cur+[x])
        rec(0, amount, [])
        return res
    nodes = [0]
    def dfs(pairs, idx, load):
        nodes[0] += 1
        if nodes[0] > node_limit:
            raise RuntimeError('limit')
        if idx == len(pairs):
            return True
        key = pairs[idx]
        amount = Lmat[key]
        dl = dists(len(pathmap[key]), amount)
        # quick check: minimal load lower bound
        for d in dl:
            newload = list(load)
            ok = True
            for cnt, pl in zip(d, ploads[key]):
                if cnt == 0: continue
                for a in pl:
                    newload[a] += cnt
                    if newload[a] > capsvec[a]:
                        ok = False; break
                if not ok: break
            if not ok: continue
            if dfs(pairs, idx+1, newload):
                return True
        return False
    # enumerate L matrices
    for combo in itertools.product(*[vecs for (v, arbs, vecs) in per_origin]):
        Lmat = defaultdict(int)
        for (v, arbs, _), wv in zip(per_origin, combo):
            for arb, w in zip(arbs, wv):
                if w == 0: continue
                for (a, b) in arb:
                    Lmat[(a, b)] += w
        pairs = sorted([k for k in Lmat if Lmat[k] > 0])
        try:
            if dfs(pairs, 0, [0]*total):
                return True, None
        except RuntimeError:
            return None, 'limit'
    return False, None

def gen(rng):
    n = rng.randint(3, 5)
    m = rng.randint(2, 3)
    parts = sorted(rng.sample(range(n), m))
    possible = [(u, v) for u in range(n) for v in range(u+1, n)]
    rng.shuffle(possible)
    nl = rng.randint(m, min(len(possible), 7))
    links = possible[:nl]
    caps = [rng.randint(0, 3) for _ in links]
    r = {v: rng.randint(0, 2) for v in parts}
    if sum(r.values()) == 0:
        r[parts[0]] = 1
    return n, links, caps, parts, r

def main():
    rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
    N = int(sys.argv[2]) if len(sys.argv) > 2 else 300
    mismatch = 0; unknown = 0
    for it in range(N):
        n, links, caps, parts, r = gen(rng)
        cd = cut_deficient(n, links, caps, parts, r)
        feas, why = brute_feasible(n, links, caps, parts, r)
        if feas is None:
            unknown += 1; continue
        if (cd is None) != feas:
            mismatch += 1
            print('MISMATCH', n, links, caps, parts, r, 'cutdef', cd, 'feas', feas, why)
            if mismatch > 8: break
    print('done', N, 'mismatches', mismatch, 'unknown', unknown)

main()
